/* ChaCha20 against RFC 8439 and against a reference implementation.
 *
 * The RFC vector (section 2.4.2) pins down the byte order, the constants and
 * the counter convention.  The generated vectors then sweep message lengths
 * around every block boundary the implementation can get wrong -- zero, one,
 * one short of a block, exactly a block, one over -- at four starting
 * counters, including 2^32-2 so that the counter is incremented into its last
 * legal value.  Finally every vector is decrypted again, which is the only
 * check that catches a keystream that is wrong in a self-consistent way.
 *
 * Generated; do not edit by hand. */

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "Hacl.h"

static int failures = 0;

static uint8_t key[32];
static uint8_t nonce[12];
static uint8_t buf[4096];
static uint8_t out[4096];
static uint8_t back[4096];

static void hex(char *dst, const uint8_t *src, size_t n) {
  for (size_t i = 0; i < n; i++)
    sprintf(dst + 2 * i, "%02x", src[i]);
}

static void check(const char *name, const uint8_t *k, const uint8_t *n,
                  uint32_t ctr, const uint8_t *msg, size_t len,
                  const char *expected) {
  char *got = malloc(2 * len + 1);

  Hacl_Chacha20_encrypt(out, (uint8_t *)msg, len, (uint8_t *)k,
                            (uint8_t *)n, ctr);
  hex(got, out, len);
  got[2 * len] = 0;

  if (strcmp(got, expected) != 0) {
    printf("  FAIL %s\n    got      %s\n    expected %s\n", name, got, expected);
    failures++;
    free(got);
    return;
  }

  Hacl_Chacha20_decrypt(back, out, len, (uint8_t *)k, (uint8_t *)n, ctr);
  if (memcmp(back, msg, len) != 0) {
    printf("  FAIL %s (round trip)\n", name);
    failures++;
  } else {
    printf("  ok   %s\n", name);
  }
  free(got);
}

